import{_ as a,o as t,c as n,a2 as o}from"./chunks/framework.G0y0PQA7.js";const i="/relio/shots/en/nav-hand-tool.png",r="/relio/shots/en/nav-find-bar.png",u=JSON.parse('{"title":"Getting around the canvas","description":"","frontmatter":{},"headers":[],"relativePath":"en/quick/navigate.md","filePath":"en/quick/navigate.md"}'),d={name:"en/quick/navigate.md"};function l(s,e,h,c,g,b){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="getting-around-the-canvas" tabindex="-1">Getting around the canvas <a class="header-anchor" href="#getting-around-the-canvas" aria-label="Permalink to &quot;Getting around the canvas&quot;">​</a></h1><p>How to move quickly around a big model and find the table you want.</p><h2 id="zoom-and-pan" tabindex="-1">Zoom and pan <a class="header-anchor" href="#zoom-and-pan" aria-label="Permalink to &quot;Zoom and pan&quot;">​</a></h2><ul><li><p><strong>Zoom in and out</strong> — <kbd>Ctrl</kbd>+mouse wheel (around the mouse pointer), or <kbd>Ctrl</kbd>+<kbd>=</kbd> · <kbd>Ctrl</kbd>+<kbd>-</kbd> · <kbd>Ctrl</kbd>+<kbd>0</kbd> (100%).</p></li><li><p><strong>Move the view</strong> — Use whichever you like:</p><ul><li>Hold <kbd>Space</kbd> and drag (release it to return to your tool)</li><li>Hand tool (<kbd>H</kbd>, from 1.0.2) — once picked, dragging even on a table only moves the view, until you press <kbd>Esc</kbd> or <kbd>V</kbd></li><li>Drag with the middle mouse button, or scroll with two fingers on a touchpad</li></ul><figure class="shot" data-scene="nav-hand-tool"><img src="'+i+'" alt="The hand tool picked in the palette" loading="lazy"><figcaption>The hand tool picked in the palette</figcaption></figure></li><li><p><strong>More room for the canvas</strong> — Double-click a document tab to collapse the right and bottom panels at once; double-click again to bring them back.</p></li></ul><h2 id="find-and-highlight" tabindex="-1">Find and highlight <a class="header-anchor" href="#find-and-highlight" aria-label="Permalink to &quot;Find and highlight&quot;">​</a></h2><ol><li>Press <kbd>Ctrl</kbd>+<kbd>F</kbd> to open the find bar over the canvas.</li><li>Type part of a table, column, relationship or note name. Every match is highlighted and everything else is dimmed. For Korean names, Hangul initial consonants also work (for example <code>ㅈㅁ</code> finds 주문, &quot;order&quot;).</li><li>Press <kbd>Enter</kbd> or <kbd>F3</kbd> for the next result and <kbd>Shift</kbd>+<kbd>Enter</kbd> for the previous one. Press <kbd>Esc</kbd> to close the bar.</li></ol><figure class="shot" data-scene="nav-find-bar"><img src="'+r+'" alt="The find bar with every matching name highlighted on the canvas" loading="lazy"><figcaption>The find bar with every matching name highlighted on the canvas</figcaption></figure><div class="tip custom-block"><p class="custom-block-title">Tip</p><p>Hover over a table or relationship line and the connected lines and tables become stronger. Click to select it and everything outside the connection is dimmed, so it stands out even more.</p></div><p><strong>More</strong> → <a href="/relio/en/features/canvas">Canvas and palette</a> · <a href="/relio/en/features/find">Find and highlight</a> · <a href="/relio/en/features/edit#find-and-replace-dialog">Edit › Find and replace dialog</a> · <a href="/relio/en/features/preferences#highlight">Settings › Highlight</a></p>',9)])])}const k=a(d,[["render",l]]);export{u as __pageData,k as default};
